[
 {
  "id": "subcon-guide-scope",
  "domain": "subcon",
  "title": "하도급법이 적용되는 거래인지 판단하기",
  "category": "적용 범위",
  "summary": "중소기업이 아닌 사업자가 중소기업에 제조·수리·건설·용역을 위탁하거나, 매출액이 더 큰 중소기업이 작은 중소기업에 위탁하면 하도급법이 적용됩니다. 상호출자제한기업집단 소속 회사는 항상 원사업자로 봅니다.",
  "sections": [
   {
    "heading": "1. 하도급거래 (제2조제1항)",
    "body": "원사업자가 수급사업자에게 제조(가공 포함)·수리·건설·용역을 위탁하거나, 다른 사업자로부터 위탁받은 것을 다시 위탁하고, 수급사업자가 그 목적물을 납품·인도·제공한 뒤 대가(하도급대금)를 받는 거래입니다."
   },
   {
    "heading": "2. 원사업자와 수급사업자 (제2조제2항·제3항)",
    "body": "원사업자: ① 중소기업자가 아닌 사업자로서 중소기업자에게 위탁한 자, ② 중소기업자 중 직전 사업연도 연간매출액(건설은 시공능력평가액, 없으면 자산총액)이 위탁받은 중소기업자보다 많은 자. 다만 ②는 시행령이 정하는 매출액 이하 중소기업자는 제외합니다.\n수급사업자: 원사업자로부터 위탁을 받은 중소기업자."
   },
   {
    "heading": "3. 특수한 경우",
    "body": "• 계열회사에 위탁하고 그 계열회사가 상당 부분을 제3자에게 다시 위탁하면, 계열회사와 제3자를 원사업자·수급사업자로 봅니다(제4항).\n• 상호출자제한기업집단 소속 회사가 위탁하면 매출액과 관계없이 원사업자로 보고, 위탁받는 경우에는 수급사업자로 보지 않습니다(제5항).\n• 연간매출액이 일정 금액 미만인 중견기업이 대기업 등으로부터 위탁받는 경우 대금 지급(제13조) 규정 등은 중견기업을 수급사업자로 보아 적용합니다(제13조제11항)."
   },
   {
    "heading": "4. 위탁 유형",
    "body": "제조위탁(제조·판매·수리·건설을 업으로 하는 사업자의 물품 제조 위탁, 물품 범위는 공정위 고시), 수리위탁, 건설위탁(건설산업기본법·전기공사업법·정보통신공사업법·소방시설공사업법상 사업자 등), 용역위탁(소프트웨어·영상·설계 등 지식·정보성과물 작성 또는 역무 공급)으로 나뉩니다(제2조제6항~제12항)."
   },
   {
    "heading": "5. 실무 체크리스트",
    "body": "• 거래 상대방의 중소기업 해당 여부와 양측의 직전 연도 매출액을 확인하세요.\n• 우리 회사가 \"그 업\"으로 하는 물품·공사·용역을 위탁하는지 확인하세요. 단순 구매는 제조위탁이 아닐 수 있습니다."
   }
  ],
  "basis": [
   {
    "label": "제2조 (정의)",
    "recordId": "subcon-law-하도급거래공정화에관한법률"
   },
   {
    "label": "제13조제11항 (중견기업 적용 특례)",
    "recordId": "subcon-law-하도급거래공정화에관한법률"
   }
  ],
  "author": "Claude 작성 · 원문 조문 근거",
  "writtenAt": "2026-10-19T13:31:22+00:00",
  "reviewedAgainst": "하도급거래 공정화에 관한 법률 시행 2026-10-02"
 },
 {
  "id": "subcon-guide-written-contract",
  "domain": "subcon",
  "title": "하도급 계약서(서면) 발급 시기와 기재사항",
  "category": "서면 발급",
  "summary": "원사업자는 수급사업자가 작업·공사·용역을 시작하기 전에 하도급대금, 조정 요건, 연동 사항 등을 적고 양측이 서명한 서면을 발급해야 합니다. 추가·변경 위탁도 같습니다.",
  "sections": [
   {
    "heading": "1. 발급 기한 (제3조제1항)",
    "body": "• 제조위탁: 납품을 위한 작업 시작 전\n• 수리위탁: 수리 시작 전\n• 건설위탁: 착공 전\n• 용역위탁: 용역 수행 시작 전\n계약 후 계약내역에 없는 추가 위탁이나 변경 위탁을 할 때도 같은 기한이 적용됩니다. 전자문서도 서면으로 인정됩니다."
   },
   {
    "heading": "2. 기재사항과 서명 (제2항)",
    "body": "하도급대금과 지급방법 등 계약 내용, 제16조의2에 따른 대금 조정 요건·방법·절차, 하도급대금 연동 사항(대상 목적물, 주요 원재료·에너지, 조정요건, 기준지표, 산식 등), 그 밖에 시행령 사항을 적고 양측이 서명(실명 확인 가능한 전자서명 포함) 또는 기명날인합니다."
   },
   {
    "heading": "3. 확정되지 않은 사항이 있을 때 (제6항·제7항)",
    "body": "재해·사고 긴급복구공사 등 정당한 사유가 있으면 위탁 시점에 정하기 어려운 사항을 비워 둔 서면을 발급할 수 있습니다. 이때 정하지 못한 이유와 예정기일을 적고, 확정되면 지체 없이 새 서면을 발급해야 합니다."
   },
   {
    "heading": "4. 서면을 받지 못한 수급사업자의 확인 요청 (제8항·제9항)",
    "body": "수급사업자는 작업 내용·하도급대금 등을 서면으로 통지해 확인을 요청할 수 있습니다. 원사업자가 15일 이내에 인정·부인 회신을 보내지 않으면 통지 내용대로 위탁이 있었던 것으로 추정합니다."
   },
   {
    "heading": "5. 실무 체크리스트",
    "body": "• 구두 발주 후 작업이 먼저 시작되지 않도록 발주 절차를 점검하세요.\n• 설계변경·추가공사도 착수 전에 변경 서면을 발급하세요.\n• 하도급거래 서류는 시행령에 따라 보존해야 합니다(제12항)."
   }
  ],
  "basis": [
   {
    "label": "제3조 (서면의 발급 및 서류의 보존)",
    "recordId": "subcon-law-하도급거래공정화에관한법률"
   }
  ],
  "author": "Claude 작성 · 원문 조문 근거",
  "writtenAt": "2026-10-19T13:31:22+00:00",
  "reviewedAgainst": "하도급거래 공정화에 관한 법률 시행 2026-10-02"
 },
 {
  "id": "subcon-guide-payment",
  "domain": "subcon",
  "title": "하도급대금 지급기한, 지연이자, 어음 할인료",
  "category": "대금 지급",
  "summary": "하도급대금은 목적물 수령일부터 60일 이내에 지급해야 합니다. 발주자에게 준공금·기성금을 받았다면 15일 이내에 지급해야 하고, 60일을 넘기면 공정위가 고시한 이율의 지연이자를 줘야 합니다.",
  "sections": [
   {
    "heading": "1. 60일 원칙 (제13조제1항·제2항)",
    "body": "목적물 수령일(건설은 인수일, 용역은 수행 완료일, 월 1회 이상 세금계산서 발행일을 정한 경우 그날)부터 60일 이내의 가능한 짧은 기한으로 정한 지급기일까지 지급합니다. 지급기일을 정하지 않았으면 수령일이 지급기일이 되고, 60일을 넘겨 정했으면 60일째 되는 날이 지급기일로 간주됩니다. 대등한 지위에서 정했거나 업종 특수성상 정당하면 예외입니다."
   },
   {
    "heading": "2. 발주자에게 돈을 받았을 때 (제3항·제4항)",
    "body": "원사업자가 발주자로부터 준공금·기성금을 받으면 받은 날부터 15일 이내(지급기일이 그보다 빠르면 그날)에 수급사업자에게 해당 금액을 지급해야 합니다. 발주자에게 받은 현금비율보다 낮은 현금비율로 지급할 수 없습니다."
   },
   {
    "heading": "3. 어음·어음대체결제수단 (제5항~제7항)",
    "body": "발주자에게 받은 어음보다 지급기간이 긴 어음을 줄 수 없고, 금융기관에서 할인 가능한 어음이어야 하며, 만기까지의 할인료를 교부일에 지급해야 합니다. 수령일부터 60일 이내에 교부하면 60일이 지난 날 이후 기간의 할인료만 지급합니다. 기업구매전용카드 등 어음대체결제수단도 같은 방식으로 수수료를 지급합니다."
   },
   {
    "heading": "4. 지연이자 (제8항)",
    "body": "수령일부터 60일이 지난 후 지급하면 초과기간에 대해 연 40% 이내에서 공정거래위원회가 고시하는 이율로 이자를 지급해야 합니다. 이율은 고시로 정하므로 지급 시점의 고시를 확인하세요."
   },
   {
    "heading": "5. 실무 체크리스트",
    "body": "• 대금 지급일 = 수령일(인수일) + 60일 이내인지 계약서와 실제 지급일을 대조하세요.\n• 기성금을 받은 날을 기록하고 15일 내 지급 일정을 관리하세요.\n• 어음 지급 시 할인료 미지급이 의결 사례에서 자주 지적됩니다."
   }
  ],
  "basis": [
   {
    "label": "제13조 (하도급대금의 지급 등)",
    "recordId": "subcon-law-하도급거래공정화에관한법률"
   }
  ],
  "author": "Claude 작성 · 원문 조문 근거",
  "writtenAt": "2026-10-19T13:31:22+00:00",
  "reviewedAgainst": "하도급거래 공정화에 관한 법률 시행 2026-10-02"
 },
 {
  "id": "subcon-guide-no-reduction",
  "domain": "subcon",
  "title": "하도급대금 감액 금지와 정당한 사유",
  "category": "부당 감액",
  "summary": "위탁할 때 정한 하도급대금은 원사업자가 정당한 사유를 입증하지 못하면 깎을 수 없습니다. 발주 취소·경기 변동, 단가 인하 소급 적용, 원사업자 부담 보험료 전가 등은 정당한 사유로 보지 않습니다.",
  "sections": [
   {
    "heading": "1. 원칙 (제11조제1항)",
    "body": "원사업자는 위탁할 때 정한 하도급대금을 감액해서는 안 됩니다. 감액하려면 정당한 사유를 원사업자가 입증해야 하고, 감액 사유와 기준 등을 적은 서면을 미리 줘야 합니다(제3항)."
   },
   {
    "heading": "2. 정당한 사유로 보지 않는 행위 (제2항)",
    "body": "1) 감액 조건을 위탁 시 명시하지 않고 협조요청·발주취소·경제상황 변동 등을 이유로 감액\n2) 단가 인하 합의 전에 위탁한 부분까지 소급 적용\n3) 현금 지급·조기 지급을 이유로 지나치게 감액\n4) 원사업자 손해에 실질적 영향이 없는 수급사업자 과오를 이유로 감액\n5) 원사업자에게서 산 물품·장비 사용료를 적정 대가 이상 공제\n6) 지급 시점 물가·자재가격 하락을 이유로 감액\n7) 경영적자·판매가격 인하 등 불합리한 이유로 감액\n8) 원사업자가 부담해야 할 고용보험료·산업안전보건관리비 등을 수급사업자에게 부담"
   },
   {
    "heading": "3. 감액분 지연이자 (제4항)",
    "body": "부당하게 감액한 금액을 수령일부터 60일이 지난 뒤 지급하면 초과기간에 대해 공정위 고시 이율(연 40% 이내)의 이자를 지급해야 합니다."
   },
   {
    "heading": "4. 실무 체크리스트",
    "body": "• 단가 인하 합의는 적용 시점을 합의일 이후 위탁분으로 한정하세요.\n• 품질 클레임 공제는 손해와의 실질적 관련성과 금액 근거를 남기세요.\n• 관련 공정위 지침: 「부당한 하도급대금 결정 및 감액행위에 대한 심사지침」(관계 법령 메뉴)"
   }
  ],
  "basis": [
   {
    "label": "제11조 (감액금지)",
    "recordId": "subcon-law-하도급거래공정화에관한법률"
   }
  ],
  "author": "Claude 작성 · 원문 조문 근거",
  "writtenAt": "2026-10-19T13:3
